package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.HashMap;
import java.util.Map.Entry;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CharsetNames;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TarArchiveInputStream_matches_TriageGen1Test {

    private static final int MIN_REQUIRED_LENGTH = TarConstants.VERSION_OFFSET + TarConstants.VERSIONLEN;

    private byte[] createSignature(String magic, String version, int totalLength) {
        byte[] sig = new byte[totalLength];
        byte[] magicBytes = magic.getBytes(StandardCharsets.US_ASCII);
        byte[] versionBytes = version.getBytes(StandardCharsets.US_ASCII);

        if (magicBytes.length > 0) {
            System.arraycopy(magicBytes, 0, sig, TarConstants.MAGIC_OFFSET, Math.min(magicBytes.length, sig.length - TarConstants.MAGIC_OFFSET));
        }
        if (versionBytes.length > 0) {
            System.arraycopy(versionBytes, 0, sig, TarConstants.VERSION_OFFSET, Math.min(versionBytes.length, sig.length - TarConstants.VERSION_OFFSET));
        }
        return sig;
    }

    @Test
    public void testMatches_LengthTooShort() {
        byte[] sig = new byte[MIN_REQUIRED_LENGTH - 1];
        assertFalse(TarArchiveInputStream.matches(sig, sig.length));
        // Test with length parameter explicitly smaller than required
        assertFalse(TarArchiveInputStream.matches(sig, sig.length));
    }




















}

